// Client-side blog search over /blog/search.json (generated by Jekyll).
// Matches on title, description, categories and tags. No dependencies.
(function () {
  var form = document.getElementById("search");
  var input = document.getElementById("q");
  var results = document.getElementById("search-results");
  var list = document.getElementById("post-list");
  var status = document.getElementById("search-status");
  var pager = document.querySelector(".pagination");
  if (!form || !input || !results || !list) return;

  var index = null;
  var indexUrl = form.getAttribute("data-search-index");

  function esc(s) {
    return String(s || "").replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function load() {
    if (index) return Promise.resolve(index);
    return fetch(indexUrl).then(function (r) { return r.json(); }).then(function (data) {
      index = data.map(function (p) {
        p._hay = [p.title, p.description, (p.categories || []).join(" "), (p.tags || []).join(" ")].join(" ").toLowerCase();
        return p;
      });
      return index;
    });
  }

  function render(items, q) {
    if (!q) {
      results.hidden = true;
      results.innerHTML = "";
      list.hidden = false;
      if (pager) pager.hidden = false;
      status.textContent = "";
      return;
    }
    list.hidden = true;
    if (pager) pager.hidden = true;
    results.hidden = false;
    status.textContent = items.length
      ? items.length + " post" + (items.length === 1 ? "" : "s") + " for “" + q + "”"
      : "Nothing found for “" + q + "”.";
    results.innerHTML = items.slice(0, 30).map(function (p) {
      return (
        '<a class="post-row" href="' + esc(p.url) + '">' +
          '<div class="post-row-thumb"><img src="' + esc(p.image) + '" alt="" loading="lazy" onerror="this.remove()"></div>' +
          '<div class="post-row-body">' +
            '<p class="post-row-meta">' +
              (p.categories && p.categories.length ? '<span class="post-row-cat">' + esc(p.categories.join(" · ")) + '</span><span aria-hidden="true">·</span>' : "") +
              '<span>' + esc(p.date) + '</span>' +
            '</p>' +
            '<h2>' + esc(p.title) + '</h2>' +
            '<p class="post-row-excerpt">' + esc(p.description) + '</p>' +
          '</div>' +
        '</a>'
      );
    }).join("");
  }

  function run() {
    var q = input.value.trim();
    if (!q) return render([], "");
    var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    load().then(function (data) {
      var hits = data.filter(function (p) {
        return terms.every(function (t) { return p._hay.indexOf(t) !== -1; });
      });
      render(hits, q);
    });
  }

  var timer;
  input.addEventListener("input", function () {
    clearTimeout(timer);
    timer = setTimeout(run, 150);
  });
  form.addEventListener("submit", function (e) { e.preventDefault(); run(); });

  // Support /blog/?q=term (used by the SearchAction structured data) and /blog/#search
  var params = new URLSearchParams(window.location.search);
  if (params.get("q")) { input.value = params.get("q"); run(); }
  if (window.location.hash === "#search") input.focus();
})();
